import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

// Unless stated otherwise, quotes are for a newcomer (0 years, first quote):
// premium = base + item surcharges + 10 % first insurance (of base) + 5 G fee.

describe("Claim Office — quote", () => {
  it.todo("empty item list → premium 5 G (only the processing fee)");

  describe("main item base premiums", () => {
    it.todo("plain sword (base 100 G) → premium 115 G");
    it.todo("plain amulet (base 60 G) → premium 71 G");
    it.todo("plain staff (base 80 G) → premium 93 G");
    it.todo("plain potion (base 40 G) → premium 49 G");
  });

  describe("components and building blocks", () => {
    it.todo("2 runes → base 50 G → premium 60 G");
    it.todo("3 runes → base 60 G (block applies) → premium 71 G");
    it.todo("4 runes → base 100 G (no block — requires exactly 3) → premium 115 G");
    it.todo("7 runes → base 175 G → 197.5 G rounded up in MHPCO's favor → premium 198 G");
    it.todo("2 runes + 1 moonstone → base 75 G (no block: different types) → premium 88 G");
    it.todo("3 runes + 3 moonstones → base 120 G (two separate blocks) → premium 137 G");
  });

  describe("item-specific modifiers", () => {
    it.todo("newcomer with cursed steel sword, enchantment 3 → premium 165 G");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies → premium 145 G");
    it.todo("cursed sword with enchantment 5 → both surcharges apply → premium 195 G");
    it.todo("sword with enchantment 4, not cursed → no surcharge → premium 115 G");
    it.todo("cursed sword with enchantment 4 → only curse surcharge → premium 165 G");
    it.todo("cursed sword + plain amulet → curse surcharge only on sword's base (160 + 50 + 16 + 5) → premium 231 G");
  });

  describe("customer modifiers", () => {
    it.todo("customer with 1 year → no loyalty discount → plain sword premium 115 G");
    it.todo("customer with exactly 2 years → loyalty discount applies → plain sword premium 95 G");
    it.todo("schema example: 5-year customer, silver amulet enchantment 2 → premium 59 G");
    it.todo("newcomer's second quote gets 15 % follow-up discount, first insurance still applies → plain sword premium 100 G");
    it.todo("3-year customer's second quote, cursed sword enchantment 7 → premium 160 G");
  });

  it.todo("quote with unknown item type (broomstick) → rejected with an error");
});

describe("Claim Office — claim", () => {
  describe("standard reimbursement", () => {
    it.todo("steel sword enchantment 3, damage 500 G → payout 400 G, remaining cap 1600 G");
    it.todo("rune, damage 200 G → payout 100 G, remaining cap 400 G");
    it.todo("schema example: amulet damaged 200 G → payout 100 G, remaining cap 1100 G");
  });

  describe("enchantment threshold vs. dragon material", () => {
    it.todo("dragon sword exactly enchantment 8, damage 1000 G → payout 400 G");
    it.todo("dragon sword enchantment 9, damage 1000 G → 50 % rule wins → payout 400 G");
    it.todo("dragon sword enchantment 5, damage 800 G → payout 700 G, remaining cap 1300 G");
    it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G");
    it.todo("payout of 350.5 G (enchantment 9, damage 901 G) is rounded down → payout 350 G");
  });

  describe("deductible per damage event", () => {
    it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G, remaining cap 2600 G");
    it.todo("two swords insured (cap 4000 G), both damaged 500 G → each own deductible → payout 800 G, remaining cap 3200 G");
  });

  describe("cap", () => {
    it.todo("cursed sword cap is 2000 G based on unmodified insurance value → damage 3000 G → payout 2000 G, remaining cap 0 G");
    it.todo("sword + 3 runes → insurance sum 1750 G, cap 3500 G → sword damage 500 G → remaining cap 3100 G");
    it.todo("two successive 1500 G claims on a sword → payouts 1400 G then 600 G, remaining caps 600 G then 0 G");
  });

  describe("invalid claims", () => {
    it.todo("more sword damages than insured swords → whole claim rejected");
    it.todo("damage to an amulet when only a sword is insured → rejected");
    it.todo("damage to an unknown item type → rejected");
    it.todo("damage with negative amount (-200) → rejected");
  });
});

describe("Claim Office — CLI", () => {
  it.todo("reads scenario JSON from stdin and writes results JSON to stdout");
  it.todo("exits non-zero with error on stderr and no results on stdout for an unknown item type");
});

