type Customer = { yearsWithMHPCO: number };
type Item = { type: string };
type Step = { op: string; items: Item[] };
type Scenario = { customer: Customer; steps: Step[] };
type StepResult = { premium: number };
type ScenarioOutcome = { results: StepResult[] };

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};
const FIRST_INSURANCE_PERCENT = 10;
const PROCESSING_FEE = 5;
const RUNE_BLOCK_SIZE = 3;
const RUNE_BLOCK_PREMIUM = 60;

// Integer percent math (amount * percent / 100) avoids float drift like 60 * 0.1.
const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

// Only the final premium is rounded — always up, in MHPCO's favor.
const roundInMHPCOsFavor = (amount: number): number => Math.ceil(amount);

// A building block requires exactly RUNE_BLOCK_SIZE runes.
const isRuneBlock = (items: Item[]): boolean =>
  items.filter((item) => item.type === "rune").length === RUNE_BLOCK_SIZE;

const sumOfBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const basePremium = (items: Item[]): number =>
  isRuneBlock(items) ? RUNE_BLOCK_PREMIUM : sumOfBasePremiums(items);

const quotePremium = (items: Item[]): number => {
  const base = basePremium(items);
  return roundInMHPCOsFavor(
    base + percentOf(base, FIRST_INSURANCE_PERCENT) + PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: [{ premium: quotePremium(scenario.steps[0].items) }],
});

