  FIRST_INSURANCE_PERCENT -
  (isLoyalCustomer(customer) ? LOYALTY_DISCOUNT_PERCENT : 0);

const quotePremium = (items: Item[], customer: Customer): number => {
  const policyBase = basePremium(items);
  return roundInMHPCOsFavor(
    policyBase +
      itemSurcharges(items) +
      percentOf(policyBase, policyModifierPercent(customer)) +
      PROCESSING_FEE,
  );
};

