// The cap is based on the policy's unmodified insurance values.
const coverageCap = (policyItems: Item[]): number =>
  CAP_MULTIPLIER *
  policyItems.reduce(
    (sum, item) => sum + ITEM_CATALOG[item.type].insuranceValue,
    0,
  );

// Each damaged item carries its own deductible.
const reimbursementFor = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const processClaim = (policyItems: Item[], damages: Damage[]): StepResult => {
  const payout = damages.reduce(
    (sum, damage) => sum + reimbursementFor(damage),
    0,
  );
  return { payout, remainingCap: coverageCap(policyItems) - payout };
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map((step, stepIndex) => {
    if (step.op === "claim") {
      const policyStep = scenario.steps[step.policy] as QuoteStep;
      return processClaim(policyStep.items, step.incident.damages);
    }
    return {
      premium: quotePremium(
        step.items,
        scenario.customer,
        isFollowUpContract(stepIndex),
      ),
    };
  }),
});
