const processClaim = (policyItems: Item[], damages: Damage[]): StepResult => {
  const cap = coverageCap(policyItems);
  const reimbursement = roundPayoutInMHPCOsFavor(
    totalReimbursement(policyItems, damages),
  );
  // MHPCO never pays out more than the policy's coverage cap.
  const payout = Math.min(cap, reimbursement);
  return { payout, remainingCap: cap - payout };
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map((step, stepIndex) => {
    if (step.op === "claim") {
      const policyStep = scenario.steps[step.policy] as QuoteStep;
      return processClaim(policyStep.items, step.incident.damages);
    }
    return {
      premium: quotePremium(
        step.items,
        scenario.customer,
        isFollowUpContract(stepIndex),
      ),
    };
  }),
});

